// Apply locally generated byte corrections with bounded buffers. Hash both ends.
import { createReadStream, createWriteStream, existsSync } from "node:fs";
import { readFile, open, rename, unlink } from "node:fs/promises";
import { resolve, sep } from "node:path";
import { createHash } from "node:crypto";
import { brotliDecompressSync, createBrotliDecompress, createBrotliCompress, constants } from "node:zlib";
import { pipeline } from "node:stream/promises";
async function digest(path) {
	const hash = createHash("sha256");
	for await (const chunk of createReadStream(path)) hash.update(chunk);
	return hash.digest("hex");
}
async function expand(source, destination) {
	await pipeline(createReadStream(source), createBrotliDecompress(), createWriteStream(destination));
}
export async function reconstructWasm(path, root, ancestors = new Set()) {
	path = resolve(path);
	if (ancestors.has(path)) throw Error("Cyclic asset reconstruction dependency");
	const dependencies = new Set(ancestors).add(path);
	if (!existsSync(path + ".recipe.json.br")) return false;
	const recipe = JSON.parse(brotliDecompressSync(await readFile(path + ".recipe.json.br")));
	const base = resolve(root, recipe.base);
	if (
		recipe.schema !== 2 ||
		!base.startsWith(resolve(root) + sep) ||
		!Number.isSafeInteger(recipe.targetBytes) ||
		recipe.targetBytes > 512 * 1024 * 1024
	)
		throw Error("Invalid Wasm reconstruction recipe");
	if (!existsSync(base)) {
		if (existsSync(base + ".recipe.json.br")) await reconstructWasm(base, root, dependencies);
		else if (existsSync(base + ".br")) await expand(base + ".br", base);
	}
	if ((await digest(base)) !== recipe.baseSha256) throw Error("Wasm reconstruction base hash mismatch");
	const difference = path + ".difference.pending",
		extra = path + ".extra.pending",
		target = path + ".pending";
	await expand(path + ".difference.br", difference);
	await expand(path + ".extra.br", extra);
	const old = await open(base, "r"),
		diff = await open(difference, "r"),
		literal = await open(extra, "r"),
		output = await open(target, "w");
	const oldSize = (await old.stat()).size;
	let oldPos = 0,
		newPos = 0,
		diffPos = 0,
		extraPos = 0;
	const buffer = Buffer.alloc(65536),
		previous = Buffer.alloc(65536);
	async function read(handle, bytes, offset, length) {
		let done = 0;
		while (done < length) {
			const r = await handle.read(bytes, done, length - done, offset + done);
			if (!r.bytesRead) throw Error("Truncated reconstruction input");
			done += r.bytesRead;
		}
	}
	async function write(length) {
		let done = 0;
		while (done < length) {
			const r = await output.write(buffer, done, length - done, newPos + done);
			if (!r.bytesWritten) throw Error("Cannot write reconstruction");
			done += r.bytesWritten;
		}
		newPos += length;
	}
	try {
		for (const command of recipe.commands) {
			if (command.length !== 3 || !command.every(Number.isSafeInteger))
				throw Error("Invalid reconstruction command");
			const [changed, added, seek] = command;
			if (changed < 0 || added < 0 || newPos + changed + added > recipe.targetBytes)
				throw Error("Reconstruction exceeds target bound");
			for (let remaining = changed; remaining;) {
				const length = Math.min(remaining, buffer.length);
				await read(diff, buffer, diffPos, length);
				previous.fill(0, 0, length);
				const first = Math.max(0, oldPos),
					last = Math.min(oldSize, oldPos + length);
				if (last > first) {
					const { bytesRead } = await old.read(previous, first - oldPos, last - first, first);
					if (bytesRead !== last - first) throw Error("Truncated base");
				}
				for (let i = 0; i < length; i++) buffer[i] = (buffer[i] + previous[i]) & 255;
				await write(length);
				oldPos += length;
				diffPos += length;
				remaining -= length;
			}
			for (let remaining = added; remaining;) {
				const length = Math.min(remaining, buffer.length);
				await read(literal, buffer, extraPos, length);
				await write(length);
				extraPos += length;
				remaining -= length;
			}
			oldPos += seek;
			if (!Number.isSafeInteger(oldPos)) throw Error("Invalid base offset");
		}
		if (newPos !== recipe.targetBytes) throw Error("Incomplete reconstructed Wasm");
	} finally {
		await Promise.all([old.close(), diff.close(), literal.close(), output.close()]);
	}
	if ((await digest(target)) !== recipe.targetSha256) throw Error("Reconstructed Wasm hash mismatch");
	await rename(target, path);
	await Promise.all([unlink(difference), unlink(extra)]);
	// Content-Encoding is a delivery representation; the release hashes logical bytes.
	await pipeline(
		createReadStream(path),
		createBrotliCompress({ params: { [constants.BROTLI_PARAM_QUALITY]: 5 } }),
		createWriteStream(path + ".br"),
	);
	return true;
}
